// Byte Quest progress, as shown on the site.
// bytequest.json is generated by `npm run sync:bytequest` (see README). Don't edit it by hand.
import snapshot from './bytequest.json';

export type BqStatus = 'up' | 'learning' | 'down';
export type BqTrack = { id: string; name: string; done: number; total: number; status: BqStatus };
export type BqPath = BqTrack & { tracks: BqTrack[] };

export const bytequest = snapshot as typeof snapshot & { paths: BqPath[] };

// Display settings ------------------------------------------------------------

// Set to false to hide Byte Quest everywhere on the site.
export const showBytequest = true;

// Paths shown in full, in this order. Other paths appear as a single line if you've started them.
export const featuredPaths = ['ccna', 'linux', 'cyber', 'sysadmin'];

// Which Byte Quest tracks count towards each roadmap hop (ids from src/data/roadmap.ts).
// Use a path id (e.g. 'cyber') to include every track in that path.
export const roadmapTracks: Record<string, string[]> = {
  foundations: ['cisco', 'ccna-core', 'lnx-shell'],
  ccna: ['ccna'],
  security: ['cyber', 'ccna-sec'],
  automation: ['python', 'pj-netinv', 'ccna-ops'],
};

// Helpers ---------------------------------------------------------------------

const allTracks = bytequest.paths.flatMap((p) => p.tracks);

/** Progress for a roadmap hop, or null if nothing is mapped to it. */
export function hopProgress(hopId: string) {
  const ids = roadmapTracks[hopId];
  if (!ids?.length) return null;
  const set = new Set<string>();
  for (const id of ids) {
    const path = bytequest.paths.find((p) => p.id === id);
    (path ? path.tracks : allTracks.filter((t) => t.id === id)).forEach((t) => set.add(t.id));
  }
  const tracks = allTracks.filter((t) => set.has(t.id));
  const done = tracks.reduce((s, t) => s + t.done, 0);
  const total = tracks.reduce((s, t) => s + t.total, 0);
  return total ? { done, total, pct: Math.round((done / total) * 100) } : null;
}

export const pct = (done: number, total: number) => (total ? Math.round((done / total) * 100) : 0);

export function syncedLabel() {
  return new Date(bytequest.syncedAt).toLocaleDateString('en-GB', { day: '2-digit', month: 'short', year: 'numeric' });
}
